/**
 * Single source of truth for "is this user Pro?" outside the signed-in web
 * flow (public API keys, Developers page). Computes the plan from
 * `User.plan` + `Subscription.currentPeriodEnd` with the same grace rule as the
 * app (`isProSubscriberPlan`) — it never relies on the lazy
 * `reconcileExpiredProSubscription`, which only runs on web requests.
 *
 * Cached per user for `API_PLAN_CACHE_TTL_MS` (default 60s) in an in-memory LRU.
 * The cache is per server instance: `invalidateUserPlan` clears this instance
 * immediately; other instances pick the change up within the TTL.
 */

import { prisma } from "@/db";
import { isProSubscriberPlan } from "@/services/billing/userPlanAccess";

export type PlanTier = "free" | "pro";

const DEFAULT_TTL_MS = 60_000;
const MAX_ENTRIES = 5_000;

function cacheTtlMs(): number {
  const raw = Number.parseInt(process.env.API_PLAN_CACHE_TTL_MS ?? "", 10);
  return Number.isFinite(raw) && raw >= 0 ? raw : DEFAULT_TTL_MS;
}

type CacheEntry = { plan: PlanTier; expiresAt: number };

// Map keeps insertion order: re-inserting on read makes it an LRU.
const cache = new Map<string, CacheEntry>();

function readCache(userId: string): PlanTier | null {
  const entry = cache.get(userId);
  if (!entry) {
    return null;
  }
  if (entry.expiresAt <= Date.now()) {
    cache.delete(userId);
    return null;
  }
  cache.delete(userId);
  cache.set(userId, entry);
  return entry.plan;
}

function writeCache(userId: string, plan: PlanTier): void {
  const ttl = cacheTtlMs();
  if (ttl === 0) {
    return;
  }
  cache.delete(userId);
  cache.set(userId, { plan, expiresAt: Date.now() + ttl });
  while (cache.size > MAX_ENTRIES) {
    const oldest = cache.keys().next().value;
    if (oldest === undefined) {
      break;
    }
    cache.delete(oldest);
  }
}

/** Effective plan for a user id (`User.id`, not the Clerk id). Unknown users are free. */
export async function getUserPlan(userId: string): Promise<PlanTier> {
  const cached = readCache(userId);
  if (cached) {
    return cached;
  }

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      plan: true,
      subscription: { select: { currentPeriodEnd: true } },
    },
  });

  const plan: PlanTier =
    user &&
    isProSubscriberPlan(user.plan, user.subscription?.currentPeriodEnd ?? null)
      ? "pro"
      : "free";

  writeCache(userId, plan);
  return plan;
}

/** Call after any plan change (payment confirmed, expiry reconciled). */
export function invalidateUserPlan(userId: string): void {
  cache.delete(userId);
}

/**
 * Public API limits per plan. `null` means the plan has no API access.
 * Add future tiers (e.g. `business`) here and to `PlanTier`.
 *
 * Every Pro number can be overridden by env (see `.env.example`).
 */

import type { PlanTier } from "@/lib/billing/plan";

export type ApiPlanLimits = {
  /** Requests per key per rolling minute. */
  requestsPerMinute: number;
  /** Accepted pipeline jobs (briefings, research) per user per UTC day. */
  pipelineJobsPerDay: number;
  /** Keys that are neither revoked nor expired. */
  maxActiveKeys: number;
};

function envInt(name: string, fallback: number): number {
  const raw = Number.parseInt(process.env[name] ?? "", 10);
  return Number.isFinite(raw) && raw > 0 ? raw : fallback;
}

export function getApiPlanLimits(plan: PlanTier): ApiPlanLimits | null {
  switch (plan) {
    case "pro":
      return {
        requestsPerMinute: envInt("API_PRO_REQUESTS_PER_MINUTE", 60),
        pipelineJobsPerDay: envInt("API_PRO_PIPELINE_JOBS_PER_DAY", 50),
        maxActiveKeys: envInt("API_PRO_MAX_ACTIVE_KEYS", 10),
      };
    case "free":
      return null;
  }
}

/** Limits shown to free users on the upgrade card. */
export function getProApiLimits(): ApiPlanLimits {
  return getApiPlanLimits("pro") as ApiPlanLimits;
}

/** Client-safe: API key scopes and their descriptions. */

export const API_SCOPES = [
  "news:read",
  "news:write",
  "research:read",
  "research:write",
  "instruments:read",
  "newsletters:read",
  "newsletters:write",
] as const;

export type ApiScope = (typeof API_SCOPES)[number];

export const API_SCOPE_DESCRIPTIONS: Record<ApiScope, string> = {
  "news:read": "Read public stories and your own briefings",
  "news:write": "Create news briefings (counts against the daily quota)",
  "research:read": "Read your stock, ETF and mutual fund research reports",
  "research:write": "Start research reports (counts against the daily quota)",
  "instruments:read": "Search stocks, ETFs and mutual funds",
  "newsletters:read": "List and read your newsletters",
  "newsletters:write": "Create, update, pause and delete your newsletters",
};

/** Pre-checked in the create dialog: read-only access plus instrument search. */
export const DEFAULT_API_SCOPES: ApiScope[] = [
  "news:read",
  "research:read",
  "instruments:read",
  "newsletters:read",
];

export const API_KEY_EXPIRY_OPTIONS = ["30", "90", "365", "never"] as const;

export type ApiKeyExpiryOption = (typeof API_KEY_EXPIRY_OPTIONS)[number];

export const API_KEY_EXPIRY_LABELS: Record<ApiKeyExpiryOption, string> = {
  "30": "30 days",
  "90": "90 days",
  "365": "1 year",
  never: "Never",
};

export type ApiKeyStatus = "active" | "revoked" | "expired" | "suspended";

/** Shape the Developers page receives — never includes the hash. */
export type SerializedApiKey = {
  id: string;
  name: string;
  prefix: string;
  scopes: ApiScope[];
  status: ApiKeyStatus;
  createdAt: string;
  lastUsedAt: string | null;
  expiresAt: string | null;
  revokedAt: string | null;
  usage: { requestsToday: number; requestsThisMonth: number; pipelineJobsToday: number };
};

export type DevelopersPayload = {
  plan: "free" | "pro";
  limits: {
    requestsPerMinute: number;
    pipelineJobsPerDay: number;
    maxActiveKeys: number;
  };
  usage: { requestsToday: number; requestsThisMonth: number; pipelineJobsToday: number };
  keys: SerializedApiKey[];
};

import { createHash, randomBytes } from "node:crypto";

export const API_KEY_PREFIX = "ds_live_";
/** Characters of the key shown in the UI (`ds_live_` + 4). */
export const API_KEY_DISPLAY_PREFIX_LENGTH = 12;

const BASE62 = "REDACTED";
const SECRET_BYTES = 32;
/** 62^43 > 2^256, so 43 chars always fit 32 bytes. */
const SECRET_LENGTH = 43;

function toBase62(bytes: Buffer): string {
  let value = BigInt(`0x${bytes.toString("hex")}`);
  let out = "";
  while (value > 0n) {
    out = BASE62[Number(value % 62n)] + out;
    value /= 62n;
  }
  return out.padStart(SECRET_LENGTH, "0");
}

/** Hex SHA-256; the only form of a key that is ever stored. */
export function hashApiKey(key: string): string {
  return createHash("sha256").update(key).digest("hex");
}

export function generateApiKey(): {
  key: string;
  prefix: string;
  hashedKey: string;
} {
  const key = `${API_KEY_PREFIX}${toBase62(randomBytes(SECRET_BYTES))}`;
  return {
    key,
    prefix: key.slice(0, API_KEY_DISPLAY_PREFIX_LENGTH),
    hashedKey: hashApiKey(key),
  };
}

/** Cheap shape check before hashing / hitting the DB. */
export function looksLikeApiKey(value: string): boolean {
  return (
    value.startsWith(API_KEY_PREFIX) &&
    value.length === API_KEY_PREFIX.length + SECRET_LENGTH &&
    /^[0-9A-Za-z]+$/.test(value.slice(API_KEY_PREFIX.length))
  );
}

