import { prisma } from "@/db";
import { createApiKeyForUser, getDevelopersPayload, revokeApiKey } from "@/services/developers/apiKeyService";
import { invalidateUserPlan } from "@/lib/billing/plan";
import { hashApiKey } from "@/lib/api/v1/keys";

const id = `tmp_stage1_${Date.now()}`;
const user = await prisma.user.create({ data: { id, clerkId: id, email: `${id}@example.test`, plan: "FREE" } });
try {
  const body = { name: "k", scopes: ["news:read" as const], expiresInDays: "30" as const };
  await createApiKeyForUser(user.id, body).then(() => console.log("FAIL free created"), (e) => console.log("free blocked:", e.constructor.name));

  await prisma.user.update({ where: { id }, data: { plan: "PRO" } });
  await prisma.subscription.create({ data: { userId: id, plan: "PRO", provider: "test", currentPeriodEnd: new Date(Date.now() + 86400e3) } });
  invalidateUserPlan(id);
  const created = [];
  for (let i = 0; i < 10; i++) created.push(await createApiKeyForUser(id, body));
  await createApiKeyForUser(id, body).then(() => console.log("FAIL 11th created"), (e) => console.log("11th blocked:", e.constructor.name));
  const first = created[0];
  const row = await prisma.apiKey.findUnique({ where: { id: first.apiKey.id } });
  console.log("hash stored, not key:", row!.hashedKey === hashApiKey(first.key), !JSON.stringify(row).includes(first.key));
  console.log("revoke own:", await revokeApiKey(id, first.apiKey.id), "revoke foreign:", await revokeApiKey("someone-else", created[1].apiKey.id));
  await createApiKeyForUser(id, body).then(() => console.log("after revoke: created ok"));

  // Lapse past grace (5 days) → suspended, without relying on lazy reconcile.
